int boton = 2;
int led = 13;
int sensor = A0;

void setup() {
    pinMode(boton, INPUT);
    pinMode(led, OUTPUT);
    Serial.begin(9600);
}

void loop() {
    // Muestrea el sensor analógico en A0
    int valor = analogRead(sensor);
    Serial.println(valor);

    // Evalúa el estado del pulsador digital
    if (digitalRead(boton) == HIGH) {
        digitalWrite(led, HIGH);
    } else {
        digitalWrite(led, LOW);
    }

    delay(200);
}
